package main

import (
	"context"
	"fmt"
	"os"
	"time"

	"github.com/egoist/mygo/ui"
	"github.com/shiuoei/print-bridge/internal/command"
)

// History export dialog.
//
// The export is generated by the command service, not here, so the file this button
// writes is byte-identical to `print-bridge history export`. The dialog only chooses
// the format and the destination, and it exports exactly the filter currently
// applied to the table.

// exportHistoryModal renders the format choice and the export action.
func (d *desktop) exportHistoryModal(c *ui.Context) {
	if d.modal.kind != modalExportHistory {
		return
	}
	open := d.modal.open
	ui.DialogBase(c, &open, func(_, _ ui.Element) {
		ui.Column(c).Gap(10).Padding(16).Width(420).Children(func() {
			ui.Text(c, d.tr("export_history_title")).FontSize(16).Bold().TextColor(palette.ink)
			ui.Text(c, d.tr("export_history_body")).FontSize(12).TextColor(palette.muted)

			// The current filter is shown explicitly: exporting silently ignored it
			// would be the kind of surprise that makes an operator distrust the file.
			// An unset filter reads as "any" rather than borrowing the status label,
			// which would print "search: Any status".
			statusLabel := d.historyFilter
			if statusLabel == "" || statusLabel == d.tr("filter_any") {
				statusLabel = d.tr("filter_any_status")
			}
			queryLabel := d.historyQuery
			if queryLabel == "" {
				queryLabel = d.tr("filter_any_query")
			}
			ui.Text(c, fmt.Sprintf(d.tr("export_history_scope"), len(d.historyJobs),
				statusLabel, queryLabel)).
				FontSize(12).TextColor(palette.ink)

			fieldLabel(c, d.tr("export_format"))
			ui.Row(c).Gap(10).Children(func() {
				for _, choice := range []struct{ value, key string }{
					{"csv", "export_format_csv"},
					{"json", "export_format_json"},
				} {
					value, label := choice.value, d.tr(choice.key)
					if d.exportHistoryFormat == value {
						if ui.PrimaryButton(c, label).Clicked() {
							d.exportHistoryFormat = value
						}
					} else if ui.Button(c, label).Clicked() {
						d.exportHistoryFormat = value
					}
				}
			})
			if d.modal.err != "" {
				ui.Text(c, d.modal.err).FontSize(12).TextColor(palette.warn)
			}
			ui.Row(c).Gap(8).Children(func() {
				if ui.Button(c, d.tr("cancel")).Clicked() {
					d.closeModal()
				}
				if ui.PrimaryButton(c, d.tr("export_history_confirm")).Clicked() {
					d.runHistoryExport()
				}
			})
		})
	})
	if !open {
		d.closeModal()
	}
}

// runHistoryExport writes the filtered history to the chosen path.
func (d *desktop) runHistoryExport() {
	format := d.exportHistoryFormat
	if format == "" {
		format = "csv"
	}
	name := "printbridge-history." + format
	path, err := d.pickSaveHistoryFile(name, format)
	if err != nil || path == "" {
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	r := d.service.Execute(ctx, command.Request{
		Command: "history.export",
		Format:  format,
		Status:  d.statusFromLabel(d.historyFilter),
		Query:   d.historyQuery,
		Limit:   50000,
	})
	if r.Error != "" {
		d.modal.err = d.errText(fmt.Errorf("%s", r.Error))
		return
	}
	if len(r.Rows) == 0 {
		d.modal.err = d.tr("export_history_empty")
		return
	}
	if err := os.WriteFile(path, r.Rows, 0o600); err != nil {
		d.modal.err = err.Error()
		return
	}
	d.closeModal()
	d.message = fmt.Sprintf(d.tr("export_history_done"), r.RowsCount, path)
	d.errorDetail = ""
}

// pickSaveHistoryFile asks for a destination with a filter matching the format.
func (d *desktop) pickSaveHistoryFile(defaultName, format string) (string, error) {
	ext := "csv"
	label := "CSV"
	if format == "json" {
		ext, label = "json", "JSON"
	}
	return saveFileDialog(d.window, d.tr("export_history_title"), defaultName,
		fileFilter{Name: label, Extensions: []string{ext}})
}
